	@Test
	public void testSortedBindingNamesShouldBeSharedWithinEvaluationContext() {
		ArrayBindingBasedQueryEvaluationContext context = new ArrayBindingBasedQueryEvaluationContext(
				new QueryEvaluationContext.Minimal(vf.createLiteral("now"), null, null),
				new String[] { "z", "a", "m" }, null);

		ArrayBindingSet left = context.createBindingSet();
		ArrayBindingSet right = context.createBindingSet();

		left.setBinding("z", RDF.ALT);
		left.setBinding("a", RDF.BAG);
		right.setBinding("z", RDF.FIRST);
		right.setBinding("a", RDF.NIL);

		List<String> leftSortedBindingNames = left.getSortedBindingNames();
		List<String> rightSortedBindingNames = right.getSortedBindingNames();

		assertEquals(List.of("a", "z"), leftSortedBindingNames);
		assertSame(leftSortedBindingNames, rightSortedBindingNames);
	}

